from typing import List

def fizzbuzz(n: int) -> List[str]:
    """Devuelve una lista de strings del 1 al n aplicando la lógica FizzBuzz."""
    resultado: List[str] = []
    for i in range(1, n + 1):
        s = str(i)
        if i % 3 == 0 and i % 5 == 0:
            s = "FizzBuzz"
        elif i % 3 == 0:
            s = "Fizz"
        elif i % 5 == 0:
            s = "Buzz"
        resultado.append(s)
    return resultado

import re

def parsear_duracion(s: str) -> int:
    """Convierte un string de duración (ej: '1h30m') a minutos totales."""
    if not s:
        return 0

    total_minutos = 0

    # Patrón para encontrar horas (h) y minutos (m)
    # Captura el número seguido de 'h' o 'm'
    matches = re.findall(r'(\d+)([hm])', s)

    for cantidad_str, unidad in matches:
        cantidad = int(cantidad_str)
        if unidad == 'h':
            total_minutos += cantidad * 60
        elif unidad == 'm':
            total_minutos += cantidad

    return total_minutos

def aplanar(lista: list) -> list:
    """Aplana una lista con sublistas anidadas a cualquier profundidad."""
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

from typing import List

def buscar(lista: List[int], x: int) -> int:
    """Busca un elemento x en una lista ordenada usando búsqueda binaria."""
    izquierda = 0
    derecha = len(lista) - 1

    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        valor_medio = lista[medio]

        if valor_medio == x:
            return medio
        elif valor_medio < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1

    return -1

from typing import List, Dict, Any

def agrupar_por(items: List[Dict[str, Any]], clave: str) -> Dict[Any, List[Dict[str, Any]]]:
    """Agrupa una lista de diccionarios por el valor de una clave específica."""
    grupos: Dict[Any, List[Dict[str, Any]]] = {}
    for item in items:
        if clave in item:
            valor_clave = item[clave]
            if valor_clave not in grupos:
                grupos[valor_clave] = []
            grupos[valor_clave].append(item)
    return grupos

