def contar_palabras(texto: str) -> Dict[str, int]:
    """Cuenta la frecuencia de cada palabra en un texto, ignorando mayúsculas y puntuación."""
    if not texto:
        return {}

    # Convertir a minúsculas y reemplazar cualquier cosa que no sea letra o espacio por un espacio
    texto_limpio = re.sub(r'[^\w\s]', ' ', texto.lower())

    # Dividir por espacios y filtrar cadenas vacías resultantes
    palabras = [palabra for palabra in texto_limpio.split() if palabra]

    return dict(Counter(palabras))

def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos."""
    if not (1 <= n <= 3999):
        raise ValueError("El número debe estar entre 1 y 3999.")

    valores = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'),
        (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'),
        (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    resultado = ""
    for valor, simbolo in valores:
        while n >= valor:
            resultado += simbolo
            n -= valor
    return resultado

def from_romano(s: str) -> int:
    """Convierte un número romano en mayúsculas a su entero correspondiente."""
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_value = 0

    # Iterar de derecha a izquierda para manejar la notación sustractiva
    for char in reversed(s):
        value = roman_map[char]

        if value < prev_value:
            total -= value
        else:
            total += value

        prev_value = value

    return total

def a_camel(s: str) -> str:
    """Convierte un string de snake_case a camelCase."""
    if not s:
        return ""
    words = s.split('_')
    if not words:
        return ""

    # La primera palabra en minúscula
    first_word = words[0].lower()

    # Las siguientes palabras con la inicial en mayúscula
    capitalized_words = [word.capitalize() for word in words[1:]]

    return first_word + "".join(capitalized_words)

import re

def a_snake(s: str) -> str:
    """Convierte una cadena de camelCase o PascalCase a snake_case."""
    if not s:
        return ""

    # Reemplaza cada transición de minúscula a mayúscula o de mayúscula a mayúscula seguida de minúscula
    # por un guion bajo seguido de la letra en mayúscula.
    s = re.sub(r'(?<!^)(?=[A-Z])', '_', s)

    return s.lower()

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    def es_primo(num: int) -> bool:
        if num < 2:
            return False
        i = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += 1
        return True

    return [num for num in range(2, n + 1) if es_primo(num)]

def mcd(a: int, b: int) -> int:
    """Calcula el máximo común divisor de dos enteros no negativos usando el algoritmo de Euclides."""
    while b:
        a, b = b, a % b
    return a

