def comprimir(s: str) -> str:
    """Aplica codificación por repeticiones si resulta en una cadena más corta."""
    if not s:
        return s

    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    compressed_parts = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 0
        j = i
        while j < len(s) and s[j] == char:
            count += 1
            j += 1
        compressed_parts.append(f"{char}{count}")
        i = j

    compressed_s = "".join(compressed_parts)

    return compressed_s if len(compressed_s) < len(s) else s

def balanceado(s: str) -> bool:
    """Devuelve True si los paréntesis, corchetes y llaves del texto están correctamente balanceados y anidados."""
    apilador = []
    mapeo = {")": "(", "]": "[", "}": "{"}

    for caracter in s:
        if caracter in "([{":
            apilador.append(caracter)
        elif caracter in ")]}":
            if not apilador:
                return False
            top_elemento = apilador.pop()
            if mapeo[caracter] != top_elemento:
                return False

    return not apilador

def raiz_digital(n: int) -> int:
    """Calcula la raíz digital de un número entero positivo."""
    if n < 0:
        raise ValueError("La raíz digital solo está definida para números no negativos.")

    while n >= 10:
        suma_digitos = 0
        # Sumar los dígitos del número actual
        temp_n = n
        while temp_n > 0:
            suma_digitos += temp_n % 10
            temp_n //= 10
        n = suma_digitos

    return n

def formatear_bytes(n: int) -> str:
    """Convierte una cantidad de bytes a texto legible usando base 1024."""
    if n < 0:
        raise ValueError("La cantidad de bytes no puede ser negativa.")
    if n == 0:
        return "0 B"

    unidades = ["B", "KB", "MB", "GB"]
    exponente = 0
    valor_flotante = float(n)

    while valor_flotante >= 1024 and exponente < len(unidades) - 1:
        valor_flotante /= 1024.0
        exponente += 1

    unidad = unidades[exponente]

    if unidad == "B":
        return f"{int(n)} B"
    else:
        return f"{valor_flotante:.1f} {unidad}"

