    """Convierte un diccionario de claves con puntos en un diccionario anidado."""
    resultado: Dict[str, Any] = {}
    for clave_con_puntos, valor in plano.items():
        partes = clave_con_puntos.split('.')
        nivel_actual = resultado
        for i, parte in enumerate(partes):
            if i == len(partes) - 1:
                nivel_actual[parte] = valor
            else:
