from typing import List

def contar_islas(grid: List[List[int]]) -> int:
    """Cuenta el número de grupos de 1 conectados en una matriz de 0 y 1."""
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    island_count = 0

    def dfs(r: int, c: int):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if visited[r][c] or grid[r][c] == 0:
            return

        visited[r][c] = True
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                island_count += 1
                dfs(r, c)

    return island_count

def a_base(n: int, base: int) -> str:
    """Convierte un entero no negativo a string en la base dada (2 a 16)."""
    if n < 0:
        raise ValueError("El entero debe ser no negativo.")
    if not (2 <= base <= 16):
        raise ValueError("La base debe estar entre 2 y 16.")
    if n == 0:
        return '0'

    DIGITS = "0123456789abcdef"
    resultado = ""
    while n > 0:
        resto = n % base
        resultado = DIGITS[resto] + resultado
        n //= base
    return resultado

from typing import List

def interseccion(a: List[int], b: List[int]) -> List[int]:
    """Devuelve la lista ordenada de valores presentes en ambas listas ordenadas, sin repetidos."""
    resultado = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            if not resultado or resultado[-1] != a[i]:
                resultado.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return resultado

def campo_csv(s: str) -> str:
