def titular(s: str) -> str:
    """Pone en mayúscula la primera letra de cada palabra, excepto ciertas preposiciones y conjunciones."""
    if not s:
        return ""

    palabras = s.lower().split()
    palabras_tituladas = []
    excepciones = {'de', 'del', 'la', 'las', 'el', 'los', 'y'}

    for i, palabra in enumerate(palabras):
        if i == 0:
            # Primera palabra siempre en mayúscula inicial
            palabras_tituladas.append(palabra.capitalize())
        elif palabra in excepciones:
            # Excepciones en minúsculas si no son la primera palabra
            palabras_tituladas.append(palabra)
        else:
            # Otras palabras: mayúscula inicial, resto minúsculas
            palabras_tituladas.append(palabra.capitalize())

    return " ".join(palabras_tituladas)

from typing import List, Any

def aplanar_hasta(lista: List[Any], profundidad: int) -> List[Any]:
    """Aplana una lista anidada solo hasta la profundidad indicada."""
    if profundidad <= 0:
        return list(lista)

    resultado = []
    for elemento in lista:
        if isinstance(elemento, list) and profundidad > 0:
            # Si es una lista y aún queda profundidad, la aplanamos recursivamente
            aplanado = aplanar_hasta(elemento, profundidad - 1)
            resultado.extend(aplanado)
        else:
            # Si no es lista o la profundidad es 0, añadimos el elemento tal cual
            resultado.append(elemento)

    return resultado

def sumar_romanos(a: str, b: str) -> str:
    """Suma dos números romanos dados como strings y devuelve el resultado en romano."""
    ROMAN_MAP = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    ROMAN_SYMBOLS = ["", "M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    def roman_to_int(roman_str: str) -> int:
        """Convierte un string romano a entero."""
        if not roman_str:
            return 0
        total = 0
        for i in range(len(roman_str)):
            value = ROMAN_MAP[roman_str[i]]
            if i > 0 and value < ROMAN_MAP[roman_str[i-1]]:
                total -= value
            else:
                total += value
        return total

    def int_to_roman(num: int) -> str:
        """Convierte un entero a string romano."""
        if num <= 0 or num >= 4000:
            # Basado en la restricción de entrada (hasta 3999), asumimos que la suma no excederá esto
            # o que el comportamiento para valores fuera de rango es no definido/no necesario.
            # Para robustez, si el resultado es inválido, devolvemos un string vacío o manejamos el error.
            # Elegimos devolver un string vacío si el número está fuera del rango esperado.
            return ""

        result = ""
        for symbol, value in zip(ROMAN_SYMBOLS, ROMAN_SYMBOLS):
            while num >= value:
                result += symbol
                num -= value
        return result

    num_a = roman_to_int(a)
    num_b = roman_to_int(b)

    suma = num_a + num_b

    return int_to_roman(suma)

from typing import Any, Dict, Optional

def obtener(d: Dict[str, Any], camino: str, defecto: Optional[Any] = None) -> Any:
    """Busca en un dict anidado siguiendo un camino con puntos y devuelve el valor o el defecto."""
    if not camino:
        return d if defecto is None else defecto

    partes_camino = camino.split('.')
    actual = d

    for parte in partes_camino:
        if isinstance(actual, dict) and parte in actual:
            actual = actual[parte]
        else:
            return defecto

    return actual

