_T = TypeVar('_T')

def con_reintentos(fn: Callable[[], _T], veces: int) -> _T:
    """Ejecuta una función con reintentos hasta un número máximo especificado."""
    if veces <= 0:
        raise ValueError("El número de veces debe ser positivo.")

    ultima_excepcion = None
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            ultima_excepcion = e
            if i < veces - 1:
                continue
            else:
                raise ultima_excepcion

